            "uid": "Mw==",
            "status": "PENDING",
            "request_quantity": 1,
            "custom_attributesV2": [
              {
                "code": "shirt_photo",
                "value": "damage_32cb1fe50dab390be841461e.png",
                "url": "https://example.com/<tenant-id>/media/rma_item/damage_32cb1fe50dab390be841461e.png?X-Amz-Algorithm=AWS4-HMAC-SHA256&X-Amz-Credential=<value>..."
