         "stock_id" : 2,
         "priority" : 1
      },
      {
        "source_code" : "west_wh",
        "stock_id" : 2,
        "priority" : 2
      },
      {
        "source_code" : "brooklyn",
        "stock_id" : 2,
        "priority" : 3
      },
      {
        "source_code" : "manhattan",
        "stock_id" : 2,
        "priority" : 4
      },
      {
        "source_code" : "huntington",
        "stock_id" : 2,
        "priority": 5
      },
      {
        "source_code" : "berkeley",
        "stock_id" : 2,
        "priority" : 6
      },
      {
         "source_code" : "sausalito",
         "stock_id" : 2,
         "priority" : 7
      },
      {
        "source_code" : "hq",
        "stock_id" : 2,
        "priority" : 8
      }
   ]
}
