```json
{
    "inventoryRequest": {
        "stockId": 2,
        "items": [{
            "sku": "24-WB01",
            "qty": 40
        },
        {
            "sku": "24-WB03",
            "qty": 20
        }]
    },
    "algorithmCode": "priority"
}
```

